describe('planBaseCompose 벡터: 옛 TS가 낸 값과 같다', () => {
  it.each(BASE)('$title', ({ config, project, expected }) => {
    expect(json(() => planBaseCompose(config as ComposeModel, project))).toBe(expected);
  });
});

describe('planReleaseCompose 벡터: 옛 TS가 낸 값과 같다', () => {
  it.each(RELEASE)('$title', ({ config, project, releaseId, images, expected }) => {
    expect(json(() => planReleaseCompose(config as ComposeModel, project, { releaseId, images }))).toBe(expected);
  });
});

describe('buildArgsFor 벡터: 옛 TS가 낸 값과 같다', () => {
  it.each(ARGS)('$title', ({ dockerfile, build, environment, expected }) => {
    expect(json(() => buildArgsFor(dockerfile, build, environment))).toBe(expected);
  });
});

describe('summarizeBuildOutput 벡터: 옛 TS가 낸 값과 같다', () => {
  it.each(SUMMARY)('$title', ({ output, max, expected }) => {
    expect(json(() => (max === undefined ? summarizeBuildOutput(output) : summarizeBuildOutput(output, max)))).toBe(expected);
  });
});

describe('buildCaddyfile 벡터: 옛 TS가 낸 값과 같다', () => {
  it.each(CADDY)('$title', ({ routes, expected }) => {
    expect(json(() => buildCaddyfile(routes))).toBe(expected);
  });
});

describe('releasesToRetire·trimRecords 벡터: 옛 TS가 낸 값과 같다', () => {
  it.each(RETIRE)('retire $title', ({ statuses, keep, expected }) => {
    const releases = statuses.map((status, k) => ({ id: String(k), status })) as unknown as DeployRelease[];
    const result = releasesToRetire(releases, keep);
    expect(JSON.stringify(result.map((release) => release.id))).toBe(expected);
    // 같은 객체를 돌려준다(부르는 쪽이 그 객체의 상태를 바꾼다)
    for (const release of result) expect(releases).toContain(release);
  });
  it.each(TRIM)('trim $title', ({ ids, active, expected }) => {
    const releases = ids.map((id, k) => ({ id, k })) as unknown as DeployRelease[];
    const result = trimRecords(releases, active);
    expect(JSON.stringify(result.map((release) => (release as unknown as { k: number }).k))).toBe(expected);
  });
});

describe('newReleaseId·이름·상태·포트 벡터', () => {
  it.each(RELEASE_IDS)('newReleaseId $title', ({ ms, expected }) => {
    expect(newReleaseId(new Date(ms))).toBe(expected);
  });
  it('deployNames와 emptyDeployState', () => {
    const names = deployNames('o$r');
    expect(JSON.stringify([names.base, names.proxy, names.release('r1'), names.image('web', 'r1'), names.container('bsd-o-r1', 'web'), emptyDeployState('o$r')])).toBe("[\"bsd-o$r-base\",\"bsd-o$r-proxy\",\"bsd-o$r-r1\",\"b-studio-deploy/o$r-web:r1\",\"bsd-o-r1-web-1\",{\"version\":1,\"project\":\"o$r\",\"ports\":{},\"releases\":[],\"history\":[]}]");
  });
  it.each(PORTS)('proxyListenPort $index', ({ index, expected }) => {
    expect(Object.is(proxyListenPort(index), expected)).toBe(true);
  });
});

